import csv

books = []

def add_book():
    author = input("Author: ")
    title = input("Title: ")
    publisher = input("Publisher: ")

    book = {
        "author": author,
        "title": title,
        "publisher": publisher
    }
    books.append(book)

def save_books():
    with open("books.csv", "w", newline='') as f:
        writer = csv.writer(f)

        writer.writerow(["author", "title", "publisher"])
        for book in books:
            writer.writerow([book['author'], books['title'], book['publisher']])

def add_books_and_save():
    while True:
        add_book()
        save_books()
        more = input('Add another book? (y/n) ')
        if more != 'y':
            break

add_books_and_save()

