    description = CharField(widget=forms.Textarea)

def add_product(request):
    if request.method == 'POST':
        form = AddProductForm(request.POST)
        if form.is_valid():
            product = form.cleaned_data
            return HttpResponse("<h1>{} added!</h1>".format(product['name']))
