def generate_noun():
    nouns = ['person', 'dog', 'cat', 'cow', 'girl', 'boy', 'bird', 'apple', 'banana', 'orange', 'computer']
    return random.choice(nouns)

def generate_joke():
    adjective1 = generate_adjective()
    noun1 = generate_noun()
    adjective2 = generate_adjective()
    noun2 = generate_noun()

    if adjective1 == 'bored':
        joke = f"Why was the {adjective1} {noun1} bored? Because they were {adjective2} {noun2} all day long!"
    else:
        joke = f"Why was the {adjective1} {noun1} {adjective2}? Because they thought they were a {noun2}!"

