import random

def gen_code():
    chars = 'abcdefg'
    return ''.join(random.choice(chars) for _ in range(9))

def generate_codes(num):
    codes = set()
    for _ in range(num):
        code = gen_code()
        while code in codes:
            code = gen_code()
        codes.add(code)
    return codes

codes = generate_codes(25)
for code in codes:
