import string
from collections import Counter, defaultdict

def count_letters(text):
    lowercase_text = text.lower()
    translation_table = str.maketrans('', '', string.punctuation)
    cleaned_text = lowercase_text.translate(translation_table)
    letters = Counter(cleaned_text)

    freqs = defaultdict(float)
    total_letters = sum(letters.values())

    for letter, count in letters.items():
        if letter in string.ascii_lowercase:
            freq = count / total_letters
            freqs[letter] = freq

    return dict(freqs)

def get_top_letters(frequencies, n=5):
    sorted_freqs = sorted(frequencies.items(), key=lambda x: x[1], reverse=True)
    return sorted_freqs[:n]

def print_justified_freqs(frequencies, decimals=4):
    max_letter_len = max(map(len, frequencies.keys()))
    pattern = f"{{letter:<{max_letter_len}}} {{freq:.{decimals}f}}"
    for letter, freq in frequencies.items():
        print(pattern.format(letter=letter, freq=freq));

def letter_stats(text):
    freqs = count_letters(text)
    top = get_top_letters(freqs, 10)
    print_justified_freqs(dict(top))

def process_book(text):
    print("Letter frequencies:", end='\n\n')

    letter_stats(text)
    letter_stats(text[::-1])
    letter_stats(text.upper())

if __name__ == '__main__':
    with open('alice_in_wonderland.txt') as f:
        text = f.read()

    process_book(text)

