import os

def get_document_filename(name):
    return name + '.txt'

def create_document(name, content):
    with open(get_document_filename(name), 'w') as f:
        f.write(content)

def update_document(name, content):
    os.chmod(get_document_filename(name), 0o777)
    with open(get_document_filename(name), 'w') as f:
        f.write(content)

def delete_document(name):
    os.remove(get_document_filename(name))

import random

def choose_outfit(weather):
    outfits = ['coat', 'jacket', 'dress', 'blouse', 'pants', 'shorts']
    if weather == 'cold':
        return random.choice(['coat', 'jacket'])
    elif weather == 'warm':
        return random.choice(['dress', 'blouse'])
    elif weather == 'hot':
        return random.choice(['pants', 'shorts'])
    else:
        return random.choice(outfits)

outfit = choose_outfit('cold')
print("You should wear " + outfit + ".")


print("Weather today is {}".format(weather))
outfit = choose_outfit(weather)
print("You should wear " + outfit + ".")

